    /**
     * Method to retrieve the Policy via an PolicyPrimaryKey.
     * @param 	id Long
     * @return 	Policy
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Policy handle( FindPolicyQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getPolicyId() );
    }
    
    /**
     * Method to retrieve a collection of all Policys
     *
     * @param	query	FindAllPolicyQuery 
     * @return 	List<Policy> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Policy> handle( FindAllPolicyQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindPolicy,
 * but only if the id matches
 *
 * @param		entity	Policy
 */
	protected void emitFindPolicy( Policy entity ) {
		LOGGER.info("handling emitFindPolicy" );
		
	    queryUpdateEmitter.emit(FindPolicyQuery.class,
	                            query -> query.getFilter().getPolicyId().equals(entity.getPolicyId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPolicy
	 * 
	 * @param		entity	Policy
	 */
	protected void emitFindAllPolicy( Policy entity ) {
		LOGGER.info("handling emitFindAllPolicy" );
		
	    queryUpdateEmitter.emit(FindAllPolicyQuery.class,
	                            query -> true,
	                            entity);
	}

